  const spot = state.nearbyNpcs.find((npc) => /fishing\s*spot/i.test(npc.name));
  if (!spot) continue;
  const netOpt = spot.optionsWithIndex.find((o) => /^net$/i.test(o.text));
  const t0 = Date.now();
  await sdk.sendInteractNpc(spot.index, netOpt.opIndex);
  // poll for catch message
  let caught = false;
  for (let t = 0; t < 20000 && !caught; t += 100) {
    const s = sdk.getState();
    const msgs = s.messages || s.recentMessages || [];
    const last = msgs.slice(-3).map(m => (typeof m === 'string' ? m : m.text || '')).join('|');
    if (/you catch/i.test(last)) { caught = true; }
    await new Promise(r => setTimeout(r, 100));
  }
  results.push(caught ? Date.now() - t0 : 'timeout');
}
return { results, messages: sdk.getState().messages?.slice(-8) };

