async function clickUntilClosed(maxSteps=8) {
  const steps = [];
  for (let i = 0; i < maxSteps; i++) {
    const d = sdk.getDialog();
    if (!d || !d.isOpen) break;
    const opts = d.options || [];
    let idx = 0;
    const yes = opts.find(o => /yes/i.test(o.text));
    const cont = opts.find(o => /continue/i.test(o.text));
    if (yes) idx = yes.index;
    else if (cont) idx = 0;
    else if (opts.length) idx = opts[opts.length-1].index;
    steps.push(idx);
    await sdk.sendClickDialog(idx);
    await sdk.waitForTicks(8);
  }
  return steps;
}
