return { steps, dialogOpen: st.dialog && st.dialog.isOpen, pos: {x: st.player.x, z: st.player.z}, gatesClosed, msgs: (st.gameMessages||[]).slice(-4).map(m=>m.text), coins: (st.inventory||[]).find(i=>/coin/i.test(i.name)) };

